   const org = await getOrgUrl();
   const result = await MicrosoftDataverseService.GetItemWithOrganization(
     READ_PREFER,
     ACCEPT,
     org,
     entityName,
     recordId,
     undefined,
     undefined,
     select?.join(','),
   );
