         <button
           type="button"
           className={`submit-screen__tab${view === "mine" ? " submit-screen__tab--active" : ""}`}
           onClick={() => setView("mine")}
         >
           My submissions ({submissions.length})
         </button>
       </nav>

       {view === "new" && <SubmissionForm tags={tags} onSave={handleCreate} capReached={capReached} />}

