28.   const [categories, setCategories] = useState<CategoryRow[]>([]);
29.   const [selectedSeasonId, setSelectedSeasonId] = useState<string | null>(null);
30.   const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
31.   const [entries, setEntries] = useState<SeasonResultEntryRow[]>([]);
32.   const [hallOfFame, setHallOfFame] = useState<HallOfFameEntryRow[]>([]);
33.   const [isLoadingShell, setIsLoadingShell] = useState(true);
34.   const [isLoadingEntries, setIsLoadingEntries] = useState(true);
35.   const [loadError, setLoadError] = useState<string | null>(null);
36. 
37.   useEffect(() => {
38.     let cancelled = false;
39.     async function load() {
40.       try {
41.         setIsLoadingShell(true);
42.         const [seasonRows, categoryRows, hallOfFameRows] = await Promise.all([
43.           listSeasons(),
